-- 028: additive transports and routing. The old claim API still serves only email/Telegram;
-- upgraded Workers use alert_claim_channels. Old dashboards/probes/senders continue to run.
begin;
alter table public.alert_channels drop constraint if exists alert_channels_kind_check;
alter table public.alert_channels add constraint alert_channels_kind_check check (kind in ('email','telegram','slack','discord','webhook'));
alter table public.alert_channels drop constraint if exists alert_channels_built;
alter table public.alert_channels add constraint alert_channels_built check
  (kind in ('email','telegram') or (sealed is not null and confirmed_at is not null and label is not null));
alter table public.alert_deliveries add column if not exists webhook_body text check (octet_length(webhook_body)<=16384);
alter table public.alert_deliveries add column if not exists webhook_started_at timestamptz;
alter table public.alert_deliveries add column if not exists webhook_attempts integer not null default 0 check(webhook_attempts between 0 and 6);

create table if not exists public.alert_routes (
  id text primary key default public.new_id('route'),
  workspace_id text not null references public.workspaces(id) on delete cascade,
  app_id text not null,
  monitor_id text,
  severity text not null check (severity in ('all','incident','warning')),
  unique(id,workspace_id),
  foreign key(app_id,workspace_id) references public.apps(id,workspace_id) on delete cascade,
  foreign key(monitor_id,workspace_id) references public.monitors(id,workspace_id) on delete cascade
);
create unique index if not exists alert_routes_app on public.alert_routes(app_id,severity) where monitor_id is null;
create unique index if not exists alert_routes_monitor on public.alert_routes(monitor_id,severity) where monitor_id is not null;
create unique index if not exists monitors_alert_route_scope on public.monitors(id,app_id,workspace_id);
do $fn$ begin
  if not exists(select 1 from pg_constraint where conrelid='public.alert_routes'::regclass and conname='alert_routes_monitor_app') then
    alter table public.alert_routes add constraint alert_routes_monitor_app
      foreign key(monitor_id,app_id,workspace_id) references public.monitors(id,app_id,workspace_id) on update cascade on delete cascade;
  end if;
}

/** A test alert sends a real message from the Alerts screen (`docs/emails.md`): a member may send
 *  a few while setting channels up, and a workspace a few dozen an hour. */
export const ALERT_TEST_BUDGET = {
  member: { limit: 10, windowSec: 600 },
  workspace: { limit: 30, windowSec: 3600 },
} as const;

/** Channel setup shares this existing budget: confirmation mail, Slack OAuth starts, and
 *  Discord/webhook creation (including DNS). The stored action remains alert_confirm so
 *  old dashboards share the same counters during rollout. */
export const ALERT_CONFIRM_BUDGET = {
  member: { limit: 5, windowSec: 3600 },
  workspace: { limit: 20, windowSec: 3600 },
} as const;

export function alertBudgetSpent(action: "alert_test" | "alert_confirm", scope: BudgetScope): string {
  const b = (action === "alert_test" ? ALERT_TEST_BUDGET : ALERT_CONFIRM_BUDGET)[scope];
  const what = action === "alert_test" ? "sent" : "used";
  const noun = action === "alert_test" ? "test alerts" : "channel setup attempts";
  return scope === "member"
    ? `You've ${what} ${b.limit} ${noun} in ${span(b.windowSec)}, which is as many as one person can.`
/* What a provider's answer to one send means to the sender (`sender.ts`), whichever provider:
   - `sent`: accepted, with the provider's id for the message.
   - `rejected`: the provider answered and refused this message; sending it again can't help.
   - `retry`: the provider answered and didn't take it, or the request never left; try later
     (after `retryAfterSec` when the provider said how long).
   - `unknown`: the request may have arrived and no answer came back. Never retried blind.

   `detail` is always our own words, never a provider's response body. */

export type SendResult =
  | { kind: "sent"; messageId: string; redirected: boolean }
  | { kind: "rejected"; code: number; detail: string }
  | { kind: "retry"; detail: string; retryAfterSec?: number }
  | { kind: "unknown"; detail: string };

/** Only failures known to precede transmission, never a generic connection loss or timeout. */
export function neverLeft(e: unknown, redirect: RequestRedirect = "follow"): boolean {
  // Workers checks this limit before starting a subrequest (docs/telegram.md). With redirects
  // enabled it could instead refuse a later hop after the original POST reached its provider,
  // so that case cannot use this proof. Other Workers network errors don't identify the phase.
  if (redirect === "manual" && e instanceof Error && e.message === "Too many subrequests.") return true;
  const code = (e as { cause?: { code?: string } })?.cause?.code;
  return code === "ENOTFOUND" || code === "ECONNREFUSED" || code === "EAI_AGAIN" || code === "UND_ERR_CONNECT_TIMEOUT";
}
